/****************************************************************************
 * ble_uart.c — BLE GATT 串口透传模块
 *
 * 基于 SiFli BLE SDK 实现 Nordic UART Service (NUS) 透传
 *
 * NUS UUID:
 *   Service: 6E400001-B5A3-F393-E0A9-E50E24DCCA9E
 *   TX Char: 6E400002-B5A3-F393-E0A9-E50E24DCCA9E (Write, 手机→板)
 *   RX Char: 6E400003-B5A3-F393-E0A9-E50E24DCCA9E Notify, 板→手机)
 *
 * 数据流：
 *   手机 APP → Write TX → 板子 rx_cb 回调
 *   板子 ble_uart_send() → Notify RX → 手机 APP 显示
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

/* SiFli BLE 头文件 */

#include "bf0_hal.h"
#include "bt_api.h"
#include "bt_gatts.h"
#include "bt_le_advertiser.h"

#include "ble_uart.h"

/****************************************************************************
 * NUS (Nordic UART Service) UUID 定义
 ****************************************************************************/

/* 128-bit Service UUID: 6E400001-B5A3-F393-E0A9-E50E24DCCA9E */

static const bt_uuid_t g_nus_svc_uuid = BT_UUID_INIT_128(
    BT_UUID_128_ENCODE(0x6E400001, 0xB5A3, 0xF393, 0xE0A9, 0xE50E24DCCA9E));

/* TX Characteristic UUID (Write, 手机→板) */

static const bt_uuid_t g_nus_tx_uuid = BT_UUID_INIT_128(
    BT_UUID_128_ENCODE(0x6E400002, 0xB5A3, 0xF393, 0xE0A9, 0xE50E24DCCA9E));

/* RX Characteristic UUID (Notify, 板→手机) */

static const bt_uuid_t g_nus_rx_uuid = BT_UUID_INIT_128(
    BT_UUID_128_ENCODE(0x6E400003, 0xB5A3, 0xF393, 0xE0A9, 0xE50E24DCCA9E));

/****************************************************************************
 * 配置参数
 ****************************************************************************/

#define BLE_UART_MAX_DATA_LEN   20    /* BLE 单包最大数据长度 */
#define BLE_UART_DEVICE_NAME    "CampusAgent"  /* 默认设备名称 */

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static struct {
  int                  initialized;     /* 是否已初始化 */
  int                  advertising;     /* 是否正在广播 */
  int                  connected;       /* 是否已连接 */
  bt_addr_t            peer_addr;       /* 对端地址 */
  uint16_t             conn_handle;     /* 连接句柄 */
  uint16_t             rx_handle;       /* RX Characteristic 句柄 */
  ble_uart_rx_cb_t     rx_cb;           /* 收到数据回调 */
  ble_uart_conn_cb_t   conn_cb;         /* 连接状态回调 */
  char                 device_name[32]; /* 设备名称 */
  pthread_mutex_t      lock;            /* 互斥锁 */
} g_ble_uart = {
  .initialized = 0,
  .advertising = 0,
  .connected   = 0,
  .conn_handle = 0,
  .rx_handle   = 0,
  .rx_cb       = NULL,
  .conn_cb     = NULL,
};

/****************************************************************************
 * BLE GATT 属性表
 ****************************************************************************/

/* GATT 属性值缓冲区 */

static uint8_t g_tx_value[BLE_UART_MAX_DATA_LEN];
static uint8_t g_rx_value[BLE_UART_MAX_DATA_LEN];
static uint16_t g_rx_cccd = 0;  /* Notify 使能标志 */

/* GATT Service 定义 */

static struct bt_gatt_attr g_nus_attrs[] = {
  /* Service Declaration */

  BT_GATT_PRIMARY_SERVICE(&g_nus_svc_uuid),

  /* TX Characteristic (Write, 手机→板) */

  BT_GATT_CHARACTERISTIC(&g_nus_tx_uuid.uuid,
                         BT_GATT_CHRC_WRITE | BT_GATT_CHRC_WRITE_WITHOUT_RESP,
                         BT_GATT_PERM_WRITE),
  BT_GATT_CCC(NULL, BT_GATT_PERM_READ | BT_GATT_PERM_WRITE),
  BT_GATT_CUD("NUS TX", BT_GATT_PERM_READ),

  /* RX Characteristic (Notify, 板→手机) */

  BT_GATT_CHARACTERISTIC(&g_nus_rx_uuid.uuid,
                         BT_GATT_CHRC_NOTIFY,
                         BT_GATT_PERM_READ),
  BT_GATT_CCC(NULL, BT_GATT_PERM_READ | BT_GATT_PERM_WRITE),
  BT_GATT_CUD("NUS RX", BT_GATT_PERM_READ),
};

static struct bt_gatt_service g_nus_svc = BT_GATT_SERVICE(g_nus_attrs);

/****************************************************************************
 * GATT 回调函数
 ****************************************************************************/

/**
 * TX Characteristic 写回调（手机发数据到板子）
 */

static ssize_t nus_tx_write_cb(struct bt_conn *conn,
                                const struct bt_gatt_attr *attr,
                                const void *buf, uint16_t len,
                                uint16_t offset, uint8_t flags)
{
  if (len > BLE_UART_MAX_DATA_LEN)
    {
      len = BLE_UART_MAX_DATA_LEN;
    }

  /* 打印收到的数据 */

  printf("[ble_uart] RX (%d bytes): ", len);
  for (int i = 0; i < len; i++)
    {
      printf("%02X ", ((uint8_t *)buf)[i]);
    }
  printf("\n");

  /* 也打印文本（如果是可打印字符） */

  printf("[ble_uart] RX text: %.*s\n", len, (char *)buf);

  /* 调用用户回调 */

  if (g_ble_uart.rx_cb)
    {
      g_ble_uart.rx_cb((const uint8_t *)buf, len);
    }

  return len;
}

/**
 * CCCD 写回调（Notify 使能/禁用）
 */

static void nus_cccd_write_cb(struct bt_conn *conn,
                               const struct bt_gatt_attr *attr,
                               uint16_t value)
{
  printf("[ble_uart] CCCD changed: 0x%04X\n", value);
  g_rx_cccd = value;
}

/****************************************************************************
 * BLE 连接回调
 ****************************************************************************/

/**
 * 连接建立回调
 */

static void connected_cb(struct bt_conn *conn, uint8_t err)
{
  if (err)
    {
      printf("[ble_uart] Connection failed (err %d)\n", err);
      return;
    }

  pthread_mutex_lock(&g_ble_uart.lock);

  g_ble_uart.connected   = 1;
  g_ble_uart.conn_handle = bt_conn_get_handle(conn);
  bt_conn_get_info(conn, NULL, &g_ble_uart.peer_addr);

  printf("[ble_uart] Connected! Handle=%d\n", g_ble_uart.conn_handle);

  /* 停止广播 */

  g_ble_uart.advertising = 0;

  pthread_mutex_unlock(&g_ble_uart.lock);

  /* 调用用户回调 */

  if (g_ble_uart.conn_cb)
    {
      g_ble_uart.conn_cb(1);
    }
}

/**
 * 连接断开回调
 */

static void disconnected_cb(struct bt_conn *conn, uint8_t reason)
{
  pthread_mutex_lock(&g_ble_uart.lock);

  printf("[ble_uart] Disconnected (reason %d)\n", reason);

  g_ble_uart.connected   = 0;
  g_ble_uart.conn_handle = 0;
  memset(&g_ble_uart.peer_addr, 0, sizeof(g_ble_uart.peer_addr));

  pthread_mutex_unlock(&g_ble_uart.lock);

  /* 调用用户回调 */

  if (g_ble_uart.conn_cb)
    {
      g_ble_uart.conn_cb(0);
    }

  /* 自动重新开始广播 */

  printf("[ble_uart] Auto-restart advertising...\n");
  ble_uart_advertise_start();
}

/* 连接回调结构体 */

static struct bt_conn_cb g_conn_callbacks = {
  .connected    = connected_cb,
  .disconnected = disconnected_cb,
};

/****************************************************************************
 * BLE 广播参数
 ****************************************************************************/

static struct bt_le_adv_param g_adv_param = {
  .options = BT_LE_ADV_OPT_CONNECTABLE | BT_LE_ADV_OPT_SCANNABLE,
  .interval_min = BT_GAP_ADV_FAST_INT_MIN_2,  /* 100ms */
  .interval_max = BT_GAP_ADV_FAST_INT_MAX_2,  /* 150ms */
};

/* 广播数据 */

static struct bt_data g_ad_data[] = {
  BT_DATA_BYTES(BT_DATA_FLAGS,
                BT_LE_AD_GENERAL | BT_LE_AD_NO_BREDR),
  BT_DATA(BT_DATA_NAME_COMPLETE,
          BLE_UART_DEVICE_NAME,
          sizeof(BLE_UART_DEVICE_NAME) - 1),
};

/* 扫描响应数据 */

static struct bt_data g_sd_data[] = {
  BT_DATA_BYTES(BT_DATA_UUID128_ALL,
                BT_UUID_128_ENCODE(0x6E400001, 0xB5A3, 0xF393,
                                   0xE0A9, 0xE50E24DCCA9E)),
};

/****************************************************************************
 * 公共 API 实现
 ****************************************************************************/

int ble_uart_init(const char *device_name,
                  ble_uart_rx_cb_t rx_cb,
                  ble_uart_conn_cb_t conn_cb)
{
  if (g_ble_uart.initialized)
    {
      printf("[ble_uart] Already initialized\n");
      return 0;
    }

  printf("[ble_uart] Initializing...\n");

  /* 初始化互斥锁 */

  pthread_mutex_init(&g_ble_uart.lock, NULL);

  /* 保存配置 */

  if (device_name)
    {
      strncpy(g_ble_uart.device_name, device_name,
              sizeof(g_ble_uart.device_name) - 1);
    }
  else
    {
      strncpy(g_ble_uart.device_name, BLE_UART_DEVICE_NAME,
              sizeof(g_ble_uart.device_name) - 1);
    }

  g_ble_uart.rx_cb   = rx_cb;
  g_ble_uart.conn_cb = conn_cb;

  /* 设置广播数据中的设备名称 */

  g_ad_data[1].data = (const uint8_t *)g_ble_uart.device_name;
  g_ad_data[1].data_len = strlen(g_ble_uart.device_name);

  /* 初始化 BLE 协议栈 */

  int ret = bt_enable(NULL);
  if (ret)
    {
      printf("[ble_uart] ERROR: bt_enable failed: %d\n", ret);
      return -1;
    }

  printf("[ble_uart] BLE stack initialized\n");

  /* 注册连接回调 */

  bt_conn_cb_register(&g_conn_callbacks);

  /* 注册 GATT Service */

  ret = bt_gatt_service_register(&g_nus_svc);
  if (ret)
    {
      printf("[ble_uart] ERROR: GATT service register failed: %d\n", ret);
      return -1;
    }

  /* 获取 RX Characteristic 句柄（用于 Notify） */

  g_ble_uart.rx_handle = bt_gatt_attr_get_handle(&g_nus_attrs[4]);

  printf("[ble_uart] GATT service registered, rx_handle=%d\n",
         g_ble_uart.rx_handle);

  g_ble_uart.initialized = 1;
  printf("[ble_uart] Init OK: device_name=\"%s\"\n",
         g_ble_uart.device_name);

  return 0;
}

int ble_uart_advertise_start(void)
{
  if (!g_ble_uart.initialized)
    {
      printf("[ble_uart] Not initialized\n");
      return -1;
    }

  if (g_ble_uart.connected)
    {
      printf("[ble_uart] Already connected, cannot advertise\n");
      return -1;
    }

  printf("[ble_uart] Starting advertising...\n");

  int ret = bt_le_adv_start(&g_adv_param,
                             g_ad_data, ARRAY_SIZE(g_ad_data),
                             g_sd_data, ARRAY_SIZE(g_sd_data));
  if (ret)
    {
      printf("[ble_uart] ERROR: adv_start failed: %d\n", ret);
      return -1;
    }

  g_ble_uart.advertising = 1;
  printf("[ble_uart] Advertising started: name=\"%s\"\n",
         g_ble_uart.device_name);

  return 0;
}

int ble_uart_advertise_stop(void)
{
  if (!g_ble_uart.advertising)
    {
      printf("[ble_uart] Not advertising\n");
      return 0;
    }

  int ret = bt_le_adv_stop();
  if (ret)
    {
      printf("[ble_uart] ERROR: adv_stop failed: %d\n", ret);
      return -1;
    }

  g_ble_uart.advertising = 0;
  printf("[ble_uart] Advertising stopped\n");
  return 0;
}

int ble_uart_send(const uint8_t *data, uint16_t len)
{
  if (!g_ble_uart.connected)
    {
      printf("[ble_uart] Not connected\n");
      return -1;
  }

  if (!g_ble_uart.rx_handle)
    {
      printf("[ble_uart] RX handle not set\n");
      return -1;
  }

  /* 检查 Notify 是否使能 */

  if (!(g_rx_cccd & BT_GATT_CCC_NOTIFY))
    {
      printf("[ble_uart] WARNING: Notify not enabled by peer\n");
    }

  /* 分包发送（每包最大 BLE_UART_MAX_DATA_LEN 字节） */

  uint16_t sent = 0;
  while (sent < len)
    {
      uint16_t chunk = len - sent;
      if (chunk > BLE_UART_MAX_DATA_LEN)
        {
          chunk = BLE_UART_MAX_DATA_LEN;
        }

      int ret = bt_gatt_notify(NULL, g_ble_uart.rx_handle,
                                data + sent, chunk);
      if (ret)
        {
          printf("[ble_uart] ERROR: notify failed: %d\n", ret);
          return -1;
        }

      sent += chunk;

      /* 分包间隔，避免 BLE 拥塞 */

      if (sent < len)
        {
          usleep(10000);  /* 10ms */
        }
    }

  return 0;
}

int ble_uart_send_string(const char *str)
{
  return ble_uart_send((const uint8_t *)str, strlen(str));
}

int ble_uart_is_connected(void)
{
  return g_ble_uart.connected;
}

int ble_uart_is_advertising(void)
{
  return g_ble_uart.advertising;
}

void ble_uart_deinit(void)
{
  if (!g_ble_uart.initialized) return;

  ble_uart_advertise_stop();

  if (g_ble_uart.connected)
    {
      /* 断开连接 */

      g_ble_uart.connected = 0;
    }

  pthread_mutex_destroy(&g_ble_uart.lock);
  g_ble_uart.initialized = 0;

  printf("[ble_uart] Deinitialized\n");
}

/****************************************************************************
 * FinSH 命令
 ****************************************************************************/

/**
 * ble_start - 启动 BLE 广播
 */

static void cmd_ble_start(int argc, char *argv[])
{
  if (!g_ble_uart.initialized)
    {
      printf("BLE not initialized. Run: ble_uart_init <name>\n");
      return;
    }

  ble_uart_advertise_start();
}

/**
 * ble_stop - 停止 BLE 广播
 */

static void cmd_ble_stop(int argc, char *argv[])
{
  ble_uart_advertise_stop();
}

/**
 * ble_status - 查看 BLE 状态
 */

static void cmd_ble_status(int argc, char *argv[])
{
  printf("=== BLE UART Status ===\n");
  printf("  Initialized:  %s\n", g_ble_uart.initialized ? "YES" : "NO");
  printf("  Advertising:  %s\n", g_ble_uart.advertising ? "YES" : "NO");
  printf("  Connected:    %s\n", g_ble_uart.connected ? "YES" : "NO");
  printf("  Device Name:  %s\n", g_ble_uart.device_name);
  if (g_ble_uart.connected)
    {
      printf("  Conn Handle:  %d\n", g_ble_uart.conn_handle);
      printf("  RX Handle:    %d\n", g_ble_uart.rx_handle);
    }
  printf("=======================\n");
}

/**
 * ble_send <text> - 发送文本到手机
 */

static void cmd_ble_send(int argc, char *argv[])
{
  if (argc < 2)
    {
      printf("Usage: ble_send <text>\n");
      return;
    }

  if (!g_ble_uart.connected)
    {
      printf("BLE not connected\n");
      return;
    }

  /* 拼接所有参数为一个字符串 */

  char buf[128];
  int offset = 0;
  for (int i = 1; i < argc && offset < sizeof(buf) - 1; i++)
    {
      if (i > 1)
        {
          buf[offset++] = ' ';
        }
      int len = strlen(argv[i]);
      if (offset + len >= sizeof(buf))
        {
          len = sizeof(buf) - offset - 1;
        }
      memcpy(buf + offset, argv[i], len);
      offset += len;
    }
  buf[offset] = '\0';

  printf("[ble_uart] Sending: %s\n", buf);
  ble_uart_send_string(buf);
  printf("[ble_uart] Sent OK\n");
}

/**
 * ble_init <name> - 初始化 BLE UART
 */

static void cmd_ble_init(int argc, char *argv[])
{
  const char *name = (argc >= 2) ? argv[1] : BLE_UART_DEVICE_NAME;
  ble_uart_init(name, NULL, NULL);
}

/* FinSH 命令注册 */

void ble_uart_register_commands(void)
{
  /* 注意：openvela 使用 NSH builtin 命令，不是 FinSH
   * 这些命令通过 CONFIG_NSH_BUILTIN_APPS 注册 */

  printf("[ble_uart] Commands: ble_init, ble_start, ble_stop, "
         "ble_status, ble_send\n");
}

/* NSH 命令入口 */

int main_ble_init(int argc, char *argv[])
{
  const char *name = (argc >= 2) ? argv[1] : BLE_UART_DEVICE_NAME;
  return ble_uart_init(name, NULL, NULL);
}

int main_ble_start(int argc, char *argv[])
{
  cmd_ble_start(argc, argv);
  return 0;
}

int main_ble_stop(int argc, char *argv[])
{
  cmd_ble_stop(argc, argv);
  return 0;
}

int main_ble_status(int argc, char *argv[])
{
  cmd_ble_status(argc, argv);
  return 0;
}

int main_ble_send(int argc, char *argv[])
{
  cmd_ble_send(argc, argv);
  return 0;
}

/****************************************************************************
 * ble_uart_test.c — BLE UART 串口透传测试程序
 *
 * 用法：nsh> ble_uart_test
 *
 * 功能：
 *   1. 初始化 BLE UART
 *   2. 启动广播
 *   3. 等待手机连接
 *   4. 接收数据并打印
 *   5. 定时发送测试数据
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <stdio.h>
#include <unistd.h>
#include "ble_uart.h"

/****************************************************************************
 * 回调函数
 ****************************************************************************/

static volatile int g_connected = 0;

/* 收到手机数据时的回调 */

static void rx_callback(const uint8_t *data, uint16_t len)
{
  printf("\n>>> 收到手机数据 (%d bytes): %.*s\n", len, len, data);

  /* 回显给手机 */

  char reply[64];
  snprintf(reply, sizeof(reply), "Echo: %.*s\n", len, data);
  ble_uart_send_string(reply);
}

/* 连接状态变化回调 */

static void conn_callback(int connected)
{
  g_connected = connected;
  if (connected)
    {
      printf("\n*** 手机已连接! ***\n");
      ble_uart_send_string("Welcome to CampusAgent!\n");
    }
  else
    {
      printf("\n*** 手机已断开! ***\n");
    }
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("\n=== BLE UART Test ===\n\n");

  /* 初始化 BLE UART */

  if (ble_uart_init("CampusAgent", rx_callback, conn_callback) < 0)
    {
      printf("ERROR: BLE UART init failed\n");
      return -1;
    }

  /* 启动广播 */

  if (ble_uart_advertise_start() < 0)
    {
      printf("ERROR: BLE advertise start failed\n");
      return -1;
    }

  printf("\n等待手机连接...\n");
  printf("请在手机上使用 BLE 调试 APP 搜索 \"CampusAgent\"\n\n");

  /* 主循环 */

  int tick = 0;
  while (1)
    {
      sleep(1);
      tick++;

      if (g_connected)
        {
          /* 每 10 秒发送一次测试数据 */

          if (tick % 10 == 0)
            {
              char msg[64];
              snprintf(msg, sizeof(msg),
                       "Heartbeat: %ds\n", tick);
              ble_uart_send_string(msg);
            }
        }
      else
        {
          /* 每 5 秒打印等待提示 */

          if (tick % 5 == 0)
            {
              printf("等待连接... (%ds)\n", tick);
            }
        }
    }

  return 0;
}

