/****************************************************************************
 * ble_uart.c — BLE GATT 串口透传模块（接口框架）
 *
 * 提供 BLE UART 透传的完整接口定义
 * 实际 BLE 功能需要根据 SiFli SDK 版本适配
 *
 * 当前实现：接口框架 + NSH 命令
 * 后续实现：调用 SiFli BLE API 完成实际功能
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#include "ble_uart.h"

/****************************************************************************
 * 配置参数
 ****************************************************************************/

#define BLE_UART_MAX_DATA_LEN   20    /* BLE 单包最大数据长度 */
#define BLE_UART_DEVICE_NAME    "CampusAgent"  /* 默认设备名称 */

/****************************************************************************
 * 内部状态
 ****************************************************************************/

static struct {
  int                  initialized;     /* 是否已初始化 */
  int                  advertising;     /* 是否正在广播 */
  int                  connected;       /* 是否已连接 */
  ble_uart_rx_cb_t     rx_cb;           /* 收到数据回调 */
  ble_uart_conn_cb_t   conn_cb;         /* 连接状态回调 */
  char                 device_name[32]; /* 设备名称 */
  pthread_mutex_t      lock;            /* 互斥锁 */
} g_ble_uart = {
  .initialized = 0,
  .advertising = 0,
  .connected   = 0,
  .rx_cb       = NULL,
  .conn_cb     = NULL,
};

/****************************************************************************
 * 公共 API 实现（接口框架）
 ****************************************************************************/

int ble_uart_init(const char *device_name,
                  ble_uart_rx_cb_t rx_cb,
                  ble_uart_conn_cb_t conn_cb)
{
  if (g_ble_uart.initialized)
    {
      printf("[ble_uart] Already initialized\n");
      return 0;
    }

  printf("[ble_uart] Initializing...\n");

  /* 初始化互斥锁 */

  pthread_mutex_init(&g_ble_uart.lock, NULL);

  /* 保存配置 */

  if (device_name)
    {
      strncpy(g_ble_uart.device_name, device_name,
              sizeof(g_ble_uart.device_name) - 1);
    }
  else
    {
      strncpy(g_ble_uart.device_name, BLE_UART_DEVICE_NAME,
              sizeof(g_ble_uart.device_name) - 1);
    }

  g_ble_uart.rx_cb   = rx_cb;
  g_ble_uart.conn_cb = conn_cb;

  /* TODO: 初始化 BLE 协议栈 */

  /* TODO: 注册 GATT Service (NUS) */

  /* TODO: 注册连接回调 */

  g_ble_uart.initialized = 1;
  printf("[ble_uart] Init OK: device_name=\"%s\"\n",
         g_ble_uart.device_name);
  printf("[ble_uart] NOTE: BLE stack integration pending\n");

  return 0;
}

int ble_uart_advertise_start(void)
{
  if (!g_ble_uart.initialized)
    {
      printf("[ble_uart] Not initialized\n");
      return -1;
    }

  if (g_ble_uart.connected)
    {
      printf("[ble_uart] Already connected, cannot advertise\n");
      return -1;
    }

  /* TODO: 启动 BLE 广播 */

  g_ble_uart.advertising = 1;
  printf("[ble_uart] Advertising started: name=\"%s\"\n",
         g_ble_uart.device_name);
  printf("[ble_uart] NOTE: BLE advertising integration pending\n");

  return 0;
}

int ble_uart_advertise_stop(void)
{
  if (!g_ble_uart.advertising)
    {
      printf("[ble_uart] Not advertising\n");
      return 0;
    }

  /* TODO: 停止 BLE 广播 */

  g_ble_uart.advertising = 0;
  printf("[ble_uart] Advertising stopped\n");
  return 0;
}

int ble_uart_send(const uint8_t *data, uint16_t len)
{
  if (!g_ble_uart.connected)
    {
      printf("[ble_uart] Not connected\n");
      return -1;
    }

  /* TODO: 通过 BLE GATT Notify 发送数据 */

  printf("[ble_uart] TX (%d bytes): %.*s\n", len, len, data);
  return 0;
}

int ble_uart_send_string(const char *str)
{
  return ble_uart_send((const uint8_t *)str, strlen(str));
}

int ble_uart_is_connected(void)
{
  return g_ble_uart.connected;
}

int ble_uart_is_advertising(void)
{
  return g_ble_uart.advertising;
}

void ble_uart_deinit(void)
{
  if (!g_ble_uart.initialized) return;

  ble_uart_advertise_stop();

  pthread_mutex_destroy(&g_ble_uart.lock);
  g_ble_uart.initialized = 0;

  printf("[ble_uart] Deinitialized\n");
}

/****************************************************************************
 * NSH 命令入口
 ****************************************************************************/

int main_ble_init(int argc, char *argv[])
{
  const char *name = (argc >= 2) ? argv[1] : BLE_UART_DEVICE_NAME;
  return ble_uart_init(name, NULL, NULL);
}

int main_ble_start(int argc, char *argv[])
{
  return ble_uart_advertise_start();
}

int main_ble_stop(int argc, char *argv[])
{
  return ble_uart_advertise_stop();
}

int main_ble_status(int argc, char *argv[])
{
  printf("=== BLE UART Status ===\n");
  printf("  Initialized:  %s\n", g_ble_uart.initialized ? "YES" : "NO");
  printf("  Advertising:  %s\n", g_ble_uart.advertising ? "YES" : "NO");
  printf("  Connected:    %s\n", g_ble_uart.connected ? "YES" : "NO");
  printf("  Device Name:  %s\n", g_ble_uart.device_name);
  printf("=======================\n");
  return 0;
}

int main_ble_send(int argc, char *argv[])
{
  if (argc < 2)
    {
      printf("Usage: ble_send <text>\n");
      return -1;
    }
  return ble_uart_send_string(argv[1]);
}

